 1:['radian'],2:['trigValue'],3:['identity'],4:['spatialAxioms'],5:['opposite'],6:['supplement'],7:['identity','supplement'],8:['addition'],9:['planeIntersection'],10:['tetrahedron'],
 13:['double'],14:['productSum'],15:['addition','double'],16:['trigDomain'],17:['planeIntersection','tetrahedron'],18:['linesPosition'],21:['parity'],22:['sinCosGraph'],23:['tanCotGraph'],24:['parallelLines'],25:['parallelLines','linesPosition'],
