 42:['arithmetic'],43:['arithmeticSum'],44:['geometric'],45:['geometricSum'],46:['arithmetic','arithmeticSum'],47:['geometric','geometricSum'],50:['arithmetic','arithmeticSum'],51:['geometric','geometricSum'],
